class WordDictionary {
    private class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isEnd = false;
    }

    private TrieNode root;

    public WordDictionary() {
        root = new TrieNode();
    }

    public void addWord(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        node.isEnd = true;
    }

    public boolean search(String word) {
        return searchHelper(word, 0, root);
    }

    private boolean searchHelper(String word, int idx, TrieNode node) {
        if (node == null) return false;
        if (idx == word.length()) return node.isEnd;

        char c = word.charAt(idx);
        if (c == '.') {
            for (TrieNode child : node.children) {
                if (searchHelper(word, idx + 1, child)) return true;
            }
            return false;
        } else {
            return searchHelper(word, idx + 1, node.children[c - 'a']);
        }
    }
}

import java.util.*;

class WordDictionary {
    private Map<Integer, List<String>> lenMap;

    public WordDictionary() {
        lenMap = new HashMap<>();
    }

    public void addWord(String word) {
        int len = word.length();
        if (!lenMap.containsKey(len)) {
            lenMap.put(len, new ArrayList<>());
        }
        lenMap.get(len).add(word);
    }

    public boolean search(String word) {
        int len = word.length();
        if (!lenMap.containsKey(len)) return false;
        List<String> candidates = lenMap.get(len);
        for (String candidate : candidates) {
            if (matches(word, candidate)) return true;
        }
        return false;
    }

    private boolean matches(String pattern, String word) {
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            if (p != '.' && p != word.charAt(i)) return false;
        }
        return true;
    }
}
